insert into public.content (key, data) values ('projects', $pf_seed$[{"slug":"document-integrity","tag":"Document forensics · Financial KYC","title":"AI Document Integrity Framework","lede":"An OCR-free forensic platform that decides whether a KYC document was tampered with, using pixels, metadata, and rendering artifacts instead of the text. Models emit signals; a deterministic risk engine makes the call and leaves an audit trail a regulator can replay.","meta":["Advora.ai","Senior AI/ML Engineer","Jan 2025 — Present","Architecture owner"],"metrics":[["0.97","AUC · tamper localization"],["0.91","AUC · resampling detection"],["8","forensic models, retrained on HITL flags"],["5","forensic layers"]],"problem":"Fraudsters edit salary slips, bank statements, and ID documents with consumer image editors. The text still reads perfectly, so OCR-based validation passes it. Banks need to know whether the pixels themselves were manipulated, where, and how confident the system is, in a form that survives regulatory review.","role":["Designed the 5-layer forensic architecture from scratch","Defined the Preprocess Bundle Contract between pipeline phases","Built the async orchestration (FastAPI → Service Bus → workers)","Set up AUC-gated retraining from human-review flags","Separated ML scoring from policy, evidence, and audit"],"arch":{"cols":["INGEST","PREPROCESS","FORENSIC LAYERS","DECIDE","EVIDENCE"],"nodes":[{"id":"api","label":"FastAPI gateway","sub":"orchestration only","col":0,"row":0,"desc":"Accepts documents, validates the request schema, writes the job, and returns immediately. No ML runs inside the API boundary, so inference load can never take the API down.","tech":["FastAPI","Pydantic","Idempotency keys"]},{"id":"bus","label":"Service Bus","sub":"job queue · DLQ","col":0,"row":1,"desc":"Decouples intake from compute. Failed jobs land in a dead-letter queue instead of disappearing, and workers scale on queue depth.","tech":["Azure Service Bus"]},{"id":"pre","label":"Preprocessing","sub":"raster · ELA · patches","col":1,"row":0,"desc":"Rasterizes every page, normalizes it, and derives ELA maps, noise residuals, and a multi-resolution patch pyramid. Every downstream layer reads the same inputs.","tech":["PyMuPDF","OpenCV","NumPy"]},{"id":"bundle","label":"Preprocess Bundle","sub":"versioned contract","col":1,"row":1,"desc":"A versioned, JSON-serializable contract that references every artifact by blob URI. Any layer can be re-run on the exact same inputs months later, which is what makes results reproducible.","tech":["JSON Schema","Blob Storage"],"contract":"bundle_version · doc_id · pages[] · artifacts{ela, noise, patches} · checksums"},{"id":"l1","label":"L1 Metadata","sub":"creation history","col":2,"row":0,"desc":"Parses PDF/XMP/EXIF structure: producer software, creation vs. modification timestamps, incremental-save history, embedded font inventory.","tech":["PDF parsing","XMP","EXIF"]},{"id":"l2","label":"L2 Global image","sub":"ELA · Noiseprint","col":2,"row":1,"desc":"Document-wide checks: error level analysis, Noiseprint camera/sensor fingerprints, compression consistency, geometry, font-rendering and anti-aliasing forensics.","tech":["ELA","Noiseprint","DCT"]},{"id":"l3","label":"L3 Patch","sub":"CNN · AE · U-Net","col":2,"row":2,"desc":"Localized detection on image patches: ResNet patch classifiers, Mahalanobis autoencoders, noise CNNs, resampling detectors, and a U-Net that outputs a pixel-level tamper mask.","tech":["PyTorch","ResNet","U-Net","Autoencoders"]},{"id":"l4","label":"L4 Cross-patch","sub":"consistency","col":2,"row":3,"desc":"Compares patches against each other with ViT embeddings, DCT/DWT frequency statistics, texture variance, and clustering. This catches regions copied from elsewhere in the same document.","tech":["ViT","DCT/DWT","Clustering"]},{"id":"fusion","label":"Fusion model","sub":"feature vector","col":3,"row":1,"desc":"Concatenates per-layer signals into a fixed feature vector and produces a calibrated tamper score. It scores; it does not decide.","tech":["Late fusion","Calibration"]},{"id":"risk","label":"Risk engine","sub":"rules · thresholds","col":3,"row":2,"decide":true,"desc":"Deterministic policy: versioned thresholds and rules map scores to risk tiers and actions (approve, human review, reject). Changing policy never requires retraining a model.","tech":["Rule engine","Versioned thresholds"]},{"id":"evidence","label":"Evidence pack","sub":"heatmaps · SHAP","col":4,"row":1,"desc":"Heatmaps, localization masks, SHAP/LIME attributions, and the exact signal values behind the decision.","tech":["SHAP","LIME","Heatmaps"]},{"id":"audit","label":"Audit log","sub":"immutable","col":4,"row":2,"decide":true,"desc":"Immutable record of every signal, threshold version, and model version used, so any decision can be replayed exactly.","tech":["PostgreSQL","Append-only"]},{"id":"hitl","label":"HITL review → retrain","sub":"AUC-gated promotion","col":4,"row":3,"desc":"Reviewer flags become versioned training sets. Retrained models are promoted only if they beat the current AUC on a held-out set.","tech":["Model registry","AUC gate"]}],"edges":[["api","bus"],["bus","pre"],["pre","bundle"],["bundle","l1"],["bundle","l2"],["bundle","l3"],["bundle","l4"],["l1","fusion"],["l2","fusion"],["l3","fusion"],["l4","fusion"],["fusion","risk"],["risk","evidence"],["risk","audit"],["audit","hitl"]]},"walkTitle":"Follow one forged bank statement through every model","walkSub":"Scroll: each model inspects the same sample document and reports what it sees. The closing balance was pasted from another document, and the bank stamp was copied from elsewhere on the page.","scene":"forensic","steps":[{"k":"intake","title":"The document arrives","body":"A borrower uploads a bank statement. To a human, and to OCR, it looks clean: the numbers are legible and the layout is right.","callout":{"t":"Input","h":"Sample bank statement","d":"Illustrative synthetic document. Two edits hidden: a pasted closing balance and a copy-moved stamp."}},{"k":"meta","title":"L1 · Metadata forensics","body":"Before looking at a pixel, the PDF's own structure is interrogated: which software produced it, when it was created and modified, and how many times it was re-saved.","detects":"Documents re-saved in image editors, timestamp inconsistencies, stripped or mismatched producer metadata.","callout":{"t":"Model · L1","h":"Metadata signal raised","d":"Producer is a consumer image editor, not the bank's statement generator.","rows":[["Detects","editor re-save · timestamp gaps"],["Input","PDF / XMP / EXIF tree"],["Signal","metadata_anomaly_score"]]}},{"k":"ela","title":"L2 · Error Level Analysis","body":"The page is recompressed at a known quality and diffed against itself. Regions that were pasted in carry a different compression history, so they light up.","detects":"Spliced text or numbers with a different JPEG history from the surrounding page.","callout":{"t":"Model · L2","h":"Compression mismatch at the balance","d":"The closing-balance field recompresses differently from the rest of the page.","rows":[["Detects","splicing · local re-edits"],["Input","page raster"],["Signal","ela_energy per region"]]}},{"k":"noise","title":"L2 · Noiseprint fingerprint","body":"Every capture pipeline leaves a faint noise signature. Noiseprint extracts it; content brought in from another source breaks the pattern.","detects":"Content spliced from a different device, scan, or source file.","callout":{"t":"Model · L2","h":"Foreign noise pattern","d":"Noise residual inside the balance field doesn't match the page's sensor fingerprint.","rows":[["Detects","cross-source splicing"],["Input","noise residual map"],["Signal","noiseprint_inconsistency"]]}},{"k":"patch","title":"L3 · Patch CNN classifier","body":"The page is cut into overlapping patches. A ResNet-based classifier scores each patch for manipulation artifacts on its own, independent of the text it contains.","detects":"Local manipulation traces: blending edges, inpainting, retouching.","callout":{"t":"Model · L3 · ResNet-CNN","h":"3 patches flagged","d":"Patch scores concentrate on the balance row; the rest of the page scores low.","rows":[["Detects","local edit artifacts"],["Input","patch pyramid"],["Signal","patch score grid"]]}},{"k":"ae","title":"L3 · Autoencoder anomaly detection","body":"An autoencoder trained only on genuine documents tries to reconstruct each patch. It can't reconstruct what it has never seen, so high reconstruction error, scored with Mahalanobis distance, means anomaly.","detects":"Novel forgery techniques that no supervised model was trained on.","callout":{"t":"Model · L3 · Mahalanobis AE","h":"Out-of-distribution region","d":"Reconstruction error spikes over the edited field. This works without labeled examples of that forgery type.","rows":[["Detects","unseen / novel edits"],["Input","patch embeddings"],["Signal","mahalanobis_distance"]]}},{"k":"resample","title":"L3 · Resampling detector","body":"Pasted content is usually scaled or rotated to fit. Interpolation leaves periodic correlations between neighboring pixels, which show up as peaks in the frequency domain.","detects":"Scaled, rotated, or warped pasted content.","callout":{"t":"Model · L3","h":"Periodic interpolation traces","d":"Spectral peaks indicate the balance was resized before pasting.","rows":[["Detects","resize · rotate · warp"],["Metric","AUC 0.91"],["Signal","resample_score"]]}},{"k":"unet","title":"L3 · U-Net localization","body":"Detection isn't enough; reviewers need to see where. A U-Net segments the page and outputs a pixel-level tamper mask.","detects":"The exact pixels that were manipulated, rendered as a mask reviewers can inspect.","callout":{"t":"Model · L3 · U-Net","h":"Pixel mask produced","d":"The mask tightly outlines the pasted digits. It becomes part of the evidence pack.","rows":[["Detects","where the edit is"],["Metric","AUC 0.97"],["Output","binary mask + heatmap"]]}},{"k":"cross","title":"L4 · Cross-patch consistency","body":"Some forgeries copy content from elsewhere in the same document, so every single-patch check passes. Comparing ViT embeddings and DCT/DWT statistics across patches finds regions that are suspiciously identical.","detects":"Copy-move forgery: stamps, signatures, or digits duplicated within the page.","callout":{"t":"Model · L4","h":"Copy-move detected","d":"The bank stamp has a near-identical twin elsewhere on the page. Genuine stamps never match pixel-for-pixel.","rows":[["Detects","copy-move · duplicated regions"],["Input","ViT embeddings · DCT/DWT"],["Signal","max_pair_similarity"]]}},{"k":"font","title":"L2 · Font-rendering forensics","body":"Text rendered by the bank's system and text typed in an editor anti-alias differently, even in the same font. Zooming to sub-pixel level exposes the seam.","detects":"Font substitution and re-typed values that visually match the original.","callout":{"t":"Model · L2","h":"Anti-aliasing mismatch","d":"The balance digits use a different rendering engine from the rest of the table.","rows":[["Detects","re-typed text · font swaps"],["Input","glyph crops"],["Signal","render_consistency"]]}},{"k":"fusion","title":"Fusion → risk engine → evidence","body":"Every layer's output becomes a feature in one vector. The fusion model produces a calibrated score; the rule engine, not the model, maps it to an action using versioned thresholds. The decision, signals, masks, and model versions are written to an immutable audit log.","detects":"Final outcome: HIGH risk, routed to human review with an evidence pack attached.","callout":{"t":"Decision","h":"Risk: HIGH → human review","d":"Rules own the decision. Changing policy means editing a threshold, not retraining a model.","rows":[["Engine","deterministic rules"],["Output","tier · action · evidence"],["Audit","signals + versions logged"]]}}],"stack":[["Forensic ML",["PyTorch","ViT","ResNet-CNN","U-Net","Mahalanobis Autoencoder","Noiseprint","ELA","DCT/DWT"]],["Orchestration",["FastAPI","Azure Service Bus","Async workers","Idempotent APIs"]],["Storage",["PostgreSQL","Azure Blob Storage","Model registry"]],["Explainability & audit",["SHAP","LIME","Heatmaps","Immutable audit log"]],["Deploy & MLOps",["Docker","AWS ECS Fargate","GitHub Actions","ECR","Secrets Manager","AUC-gated promotion"]]],"decisions":[{"h":"OCR-free by design","c":"Analyze pixels and structure, not text","p":"A forged number reads perfectly, so text-level validation is blind to the attack. Forensic signals attack the forgery process itself.","t":"Heavier compute per page; offset by async workers scaling on queue depth."},{"h":"Models score, rules decide","c":"Fusion model → deterministic risk engine","p":"Regulators ask why a document was rejected. Versioned rules and thresholds give a replayable answer, and policy can change without retraining.","t":"Two systems to maintain instead of one end-to-end classifier."},{"h":"Versioned Preprocess Bundle","c":"One immutable input contract for every layer","p":"Every layer reads identical artifacts, so results can be reproduced exactly. That is non-negotiable for audit.","t":"Extra storage for derived artifacts."},{"h":"No ML inside the API","c":"API orchestrates; workers infer","p":"Inference spikes can't degrade intake, and the dead-letter queue keeps failed jobs visible.","t":"Clients must poll or receive webhooks instead of a synchronous answer."}],"showInGrid":false},{"slug":"voice-ai-platform","tag":"Voice AI · Real-estate presales","title":"Multi-Agent Voice AI Platform","lede":"A config-driven, multi-tenant voice platform for Indian real-estate presales. Seven agents run lead qualification through post-booking collections, in Hinglish, over real phone lines. New verticals ship as declarative configuration, not code.","meta":["Advora.ai","Architecture & product","2026"],"metrics":[["7","specialized agents"],["3-tier","cost-aware turn router"],["Hinglish","code-switching"],["0","AI-led negotiation (hard rule)"]],"problem":"Presales teams lose leads in the first hour, and most early calls are repetitive qualification. Voice AI has to work over noisy narrowband phone audio, handle Hinglish, stay within TRAI and DPDP rules, and write clean data back to the CRM, while keeping per-call cost low enough to run on every lead.","role":["Architected the modular monolith and Industry Pack model","Designed the planner/executor loop and tool registry","Designed the cost-tiered turn router","Designed hybrid retrieval and CRM sync via transactional outbox","Built compliance into the architecture (pre-dial gate, guardrails)"],"arch":{"cols":["CHANNEL","SPEECH","REASONING","KNOWLEDGE & TOOLS","SYSTEMS OF RECORD"],"nodes":[{"id":"trigger","label":"Lead trigger","sub":"portal · ads · IVR","col":0,"row":0,"desc":"New enquiries from property portals, ad forms, the website, and missed calls trigger an outbound qualification call.","tech":["Webhooks","Lead ingestion"]},{"id":"gate","label":"Pre-dial gate","sub":"DND · calling window","col":0,"row":1,"decide":true,"desc":"Deterministic checks before any call: DND registry, permitted calling windows, consent, and data quality. A call that fails the gate never dials.","tech":["TRAI TCCCPR","DPDP Act 2023","Rules"]},{"id":"stt","label":"Streaming STT","sub":"turn detection","col":1,"row":0,"desc":"Streaming transcription with turn detection and barge-in, behind a provider abstraction so vendors can be swapped per language or cost.","tech":["Sarvam","Gnani","Deepgram"]},{"id":"tts","label":"Streaming TTS","sub":"+ pre-rendered cache","col":1,"row":1,"desc":"Streaming synthesis for dynamic replies; fixed utterances (greetings, confirmations) are pre-rendered and cached to cut latency and cost.","tech":["Sarvam","ElevenLabs","TTS cache"]},{"id":"router","label":"Turn router","sub":"3 tiers","col":2,"row":0,"desc":"Routes each turn to the cheapest layer that can handle it: deterministic state machine first, then a small model, and a frontier model only when needed.","tech":["State machine","Small LLM","Frontier LLM"]},{"id":"planner","label":"Planner / executor","sub":"7 agents","col":2,"row":1,"desc":"Agents plan tool calls and execute them with deterministic validation. The seven agents cover qualification, site visits, follow-ups, and collections.","tech":["Planner/executor","YAML rule engine","Journey state machine"]},{"id":"tools","label":"Tool registry","sub":"pre/postconditions","col":3,"row":0,"desc":"Declarative tools with preconditions, postconditions, and idempotency keys. An agent cannot call a tool whose preconditions fail, and retries never double-book.","tech":["Declarative registry","Idempotency"]},{"id":"rag","label":"Hybrid retrieval","sub":"pgvector + tsvector","col":3,"row":1,"desc":"Project knowledge (amenities, policies, FAQs) retrieved with pgvector HNSW and Postgres full-text search, merged with Reciprocal Rank Fusion. Prices and inventory come from structured lookups, never RAG.","tech":["pgvector HNSW","tsvector","RRF"]},{"id":"outbox","label":"Transactional outbox","sub":"fan-out","col":4,"row":0,"desc":"State changes and CRM updates commit in the same transaction as an outbox row, then fan out to the CRM, dashboards, and analytics. No lost or duplicated updates.","tech":["Outbox pattern","WebSockets"]},{"id":"crm","label":"CRM","sub":"LeadSquared · Sell.do","col":4,"row":1,"desc":"Structured write-back after every call: budget, configuration, timeline, intent, disposition, and summary.","tech":["LeadSquared","Sell.do"]},{"id":"trace","label":"Decision traces","sub":"explainability log","col":4,"row":2,"decide":true,"desc":"Every routing decision, tool call, and rule evaluation is logged with its inputs, so any call can be explained after the fact.","tech":["decision_traces","PostgreSQL"]}],"edges":[["trigger","gate"],["gate","stt"],["stt","router"],["router","planner"],["planner","tools"],["planner","rag"],["tools","outbox"],["planner","tts"],["outbox","crm"],["planner","trace"]]},"walkTitle":"One call turn, end to end","walkSub":"Scroll to follow a single Hinglish exchange: what the caller says, how the platform routes it, which tools fire, and what reaches the CRM. Conversation and payloads are illustrative.","scene":"call","steps":[{"k":"trigger","node":"trigger","title":"Lead captured, gate checked","body":"A portal enquiry arrives. Before dialing, the pre-dial gate checks the DND registry, the permitted calling window, and data quality. Only then does the call go out.","detects":"Compliance is enforced by the architecture: a call that fails the gate is impossible, not just discouraged.","payload":"{\n  \"lead_id\": \"L-20931\",\n  \"source\": \"portal\",\n  \"gate\": { \"dnd\": \"clear\", \"window\": \"ok\", \"consent\": \"ok\" },\n  \"action\": \"dial\"\n}","callout":{"t":"Pre-dial gate","h":"Cleared to dial","d":"DND, calling window, and consent all pass."}},{"k":"stt","node":"stt","title":"Streaming speech-to-text","body":"The caller answers in Hinglish. Partial transcripts stream in; turn detection decides when they've finished speaking, and barge-in lets them interrupt the agent naturally.","payload":"{\n  \"text\": \"haan, 3BHK chahiye, budget 1.2 crore ke around\",\n  \"lang\": \"hi-en\",\n  \"final\": true\n}","callout":{"t":"STT","h":"Final transcript","d":"Code-switched speech transcribed as one turn."}},{"k":"router","node":"router","title":"Turn router picks the cheapest tier","body":"This turn is slot-filling: configuration and budget. The deterministic state machine can handle it, so no LLM call is made at all.","detects":"Cost control: rules → small model → frontier. Most qualification turns never reach an LLM.","payload":"{\n  \"tier\": \"T1_state_machine\",\n  \"slots\": { \"config\": \"3BHK\", \"budget_inr\": 12000000 },\n  \"llm_calls\": 0\n}","callout":{"t":"Router","h":"Tier 1: state machine","d":"Slot-fill handled deterministically. No model invoked."}},{"k":"tools","node":"tools","title":"Planner calls a registered tool","body":"The planner checks matching inventory. The tool registry verifies preconditions (project active, budget present) and attaches an idempotency key so a retry can't create duplicate holds.","payload":"// tool call\ncheck_inventory(\n  project=\"Skyline Residences\",\n  config=\"3BHK\", max_price=12000000\n)\n// pre ✓ project_active  ✓ budget_set\n// idempotency_key: L-20931:inv:1","callout":{"t":"Tool registry","h":"Preconditions passed","d":"Declarative contract checked before execution."}},{"k":"rag","node":"rag","title":"Facts from tables, context from RAG","body":"Price and availability come from a structured lookup: numbers are never generated. Amenity questions go to hybrid retrieval (pgvector + full-text, merged with RRF).","detects":"Why: an LLM paraphrasing a price is a compliance incident. Numeric facts bypass generation entirely.","payload":"{\n  \"structured\": { \"units_available\": 4, \"from_inr\": 11400000 },\n  \"rag\": { \"method\": \"RRF(pgvector, tsvector)\", \"top_k\": 3 }\n}","callout":{"t":"Knowledge","h":"Structured fact + retrieved context","d":"Numbers from tables; prose context from hybrid search."}},{"k":"tts","node":"tts","title":"Reply spoken back","body":"The response streams through TTS. Fixed phrases come from a pre-rendered cache, and dynamic parts are synthesized, keeping first-audio latency low.","payload":"{\n  \"reply\": \"Ji, Skyline mein 3BHK 1.14 crore se available hai. Kya aap is weekend site visit karna chahenge?\",\n  \"cached_segments\": 1\n}","callout":{"t":"TTS","h":"Response streamed","d":"Cached greeting + synthesized details."}},{"k":"crm","node":"outbox","title":"CRM write-back via outbox","body":"The visit booking and qualification fields commit with an outbox row in one transaction, then fan out to the CRM, dashboard, and analytics. Every decision on this call is in the trace log.","detects":"No lost updates, no double writes, and every agent decision explainable afterwards.","payload":"{\n  \"crm_update\": {\n    \"config\": \"3BHK\", \"budget\": \"1.2Cr\",\n    \"intent\": \"high\", \"site_visit\": \"Sat 11:00\"\n  },\n  \"trace_id\": \"dt_7f3a\"\n}","callout":{"t":"Systems of record","h":"CRM updated · trace logged","d":"Transactional outbox guarantees delivery."}}],"stack":[["Speech",["Streaming STT/TTS","Turn detection","Barge-in","Sarvam","Gnani","Deepgram","ElevenLabs"]],["Reasoning",["Planner/executor","Tool registry","YAML rule engine","State machine","3-tier routing"]],["Knowledge",["PostgreSQL","pgvector HNSW","tsvector","RRF"]],["Integration",["FastAPI","Transactional outbox","WebSockets","LeadSquared","Sell.do"]],["Compliance",["DPDP Act 2023","TRAI TCCCPR","Pre-dial gate","Decision traces"]]],"decisions":[{"h":"Modular monolith, not microservices","c":"One deployable, strict module boundaries","p":"A small team shipping fast doesn't need network hops between every component. Module boundaries keep extraction possible later.","t":"Scaling is coarser-grained until modules are extracted."},{"h":"Industry Packs as configuration","c":"Verticals are YAML bundles","p":"Scripts, slots, rules, and tools per vertical are data. A new vertical is a config review, not a release.","t":"Config needs its own validation and testing discipline."},{"h":"Cheapest capable tier first","c":"State machine → small model → frontier","p":"Most presales turns are predictable. Routing them away from LLMs cuts cost and latency and removes a hallucination surface.","t":"The state machine must be maintained as scripts evolve."},{"h":"No AI-led negotiation","c":"Hard guardrail on the Collection Agent","p":"Waivers and payment negotiation carry legal and financial risk. The agent captures promises-to-pay and escalates; humans negotiate.","t":"Some collection conversations need a human handoff."}],"showInGrid":false},{"slug":"ai-insights-kyc","tag":"Analytics · Lending & real estate","title":"AI Insights & KYC STP Engines","lede":"Two decision-support systems built on one principle: statistics find the signal, rules decide, and the LLM only writes prose it cannot falsify. A funnel intelligence platform for a real-estate developer and a KYC straight-through-processing framework for NBFC lending.","meta":["Advora.ai","Architecture","2026"],"metrics":[["24","KYC failure modes mapped"],["5","failure layers (L1–L5)"],["3-tier","resolution model"],["0","numbers the LLM can invent"]],"problem":"Sales leaders were stitching Excel exports to understand why leads stalled, and lenders were losing borrowers to KYC failures that could have self-resolved. Both needed insight they could act on, without an LLM confidently narrating wrong numbers.","role":["Architected the canonical event model and metric contracts","Designed the anomaly engine for low-volume data","Designed the LLM narrative layer with numeric validation","Built the KYC failure taxonomy and resolution tiers","Enforced non-surveillance through schema separation"],"arch":{"cols":["SOURCES","MODEL","DETECT","EXPLAIN","DELIVER"],"nodes":[{"id":"src","label":"Unified capture","sub":"portals · ads · IVR · CRM","col":0,"row":0,"desc":"All lead sources land in one ingestion path with a data-quality gate.","tech":["Connectors","Webhooks"]},{"id":"kyc","label":"KYC signals","sub":"V-CIP · eKYC · CKYC · AA","col":0,"row":2,"desc":"KYC events from video KYC, eKYC, CKYC lookups, and Account Aggregator flows feed the STP framework.","tech":["V-CIP","eKYC","CKYC","Account Aggregator"]},{"id":"idr","label":"Identity resolution","sub":"phone-hash dedupe","col":1,"row":0,"desc":"Duplicate leads across sources are merged on a hashed phone key, which also puts a number on the cost of duplicate paid leads.","tech":["Hashing","Dedupe"]},{"id":"events","label":"Stage-transition events","sub":"append-only","col":1,"row":1,"desc":"One append-only table of stage transitions. Every funnel metric, anomaly, and feature derives from it, so history is never rewritten.","tech":["PostgreSQL","Event sourcing"],"contract":"lead_id · from_stage · to_stage · ts · source · actor_role"},{"id":"metrics","label":"Metric contracts","sub":"versioned","col":2,"row":0,"desc":"Every metric has a signed, versioned definition (dedupe rules, booking vs. cancellation, stage regressions) before any SQL is written.","tech":["Metric dictionary","Versioning"]},{"id":"anom","label":"Anomaly engine","sub":"beta-binomial","col":2,"row":1,"desc":"Conversion rates on small per-project volumes are modeled with beta-binomial posteriors over rolling windows, avoiding false alarms from noise.","tech":["Bayesian","Rolling windows"]},{"id":"taxonomy","label":"Failure taxonomy","sub":"L1–L5 · 24 modes","col":2,"row":2,"desc":"KYC failures classified into five layers and 24 specific failure modes, each mapped to a resolution path.","tech":["Taxonomy","Rules"]},{"id":"hyp","label":"Hypothesis library","sub":"rule-selected","col":3,"row":1,"desc":"Detected anomalies are matched to a curated library of explanations, selected by rules rather than invented by a model.","tech":["Rules","Templates"]},{"id":"llm","label":"LLM narrator","sub":"+ numeric validator","col":3,"row":0,"decide":true,"desc":"The LLM only turns a structured Insight Object into prose. A validator rejects any output containing a number not present in the source object.","tech":["LLM","Numeric validator"]},{"id":"tiers","label":"Resolution tiers","sub":"auto · guided · human","col":3,"row":2,"decide":true,"desc":"T1 auto-resolve, T2 borrower-guided fix, T3 human review, routed deterministically from the failure mode.","tech":["Routing rules"]},{"id":"out","label":"Alerts & CRM","sub":"digest · write-back","col":4,"row":1,"desc":"Insights reach the right owner as a daily digest and CRM write-back, reported at project and team level, never per rep.","tech":["WhatsApp/email digest","CRM"]}],"edges":[["src","idr"],["idr","events"],["events","metrics"],["events","anom"],["metrics","anom"],["anom","hyp"],["hyp","llm"],["llm","out"],["kyc","taxonomy"],["taxonomy","tiers"],["tiers","out"]]},"walkTitle":"From raw leads to an insight you can trust","walkSub":"Scroll through the pipeline. Charts use illustrative data.","scene":"insights","steps":[{"k":"capture","node":"src","title":"Every source, one pipe","body":"Portal leads, ad forms, website enquiries, and missed calls arrive through one ingestion path with a quality gate.","callout":{"t":"Capture","h":"4 sources unified","d":"One schema regardless of origin."}},{"k":"dedupe","node":"idr","title":"Identity resolution","body":"The same buyer often enquires through three portals. Hashing phone numbers merges them into one identity and quantifies how much ad spend bought duplicates.","detects":"Duplicate paid leads, inflated funnel counts.","callout":{"t":"Identity","h":"3 records → 1 buyer","d":"Merged on a hashed phone key."}},{"k":"funnel","node":"events","title":"An append-only event spine","body":"Stage changes are appended, never updated. Funnel conversion, time-in-stage, and drop-off are all computed from this one table.","callout":{"t":"Events","h":"Funnel from transitions","d":"Lead → Qualified → Visit → Booking."}},{"k":"anomaly","node":"anom","title":"Anomalies without false alarms","body":"With a few dozen leads per project per week, percentages swing wildly. Beta-binomial posteriors give a credible interval; an alert fires only when the observed rate falls outside it.","detects":"Real drops in conversion, not noise from small samples.","callout":{"t":"Anomaly engine","h":"Visit rate below credible band","d":"Alert fires; noise-level dips don't."}},{"k":"narrate","node":"llm","title":"The LLM writes; the validator checks","body":"The anomaly and its matched hypothesis form a structured Insight Object. The LLM turns it into a readable sentence, and a validator rejects the output if it contains any number not in the object.","detects":"Hallucinated figures are blocked before anyone sees them.","payload":"{\n  \"insight\": \"site_visit_rate_drop\",\n  \"project\": \"P-07\",\n  \"observed\": 0.18, \"band\": [0.24, 0.41],\n  \"hypothesis\": \"source_mix_shift\",\n  \"owner_role\": \"presales_lead\"\n}\n// validator: every number in prose ∈ object ✓","callout":{"t":"Narrative","h":"Validated insight","d":"What happened → likely cause → next action → owner."}},{"k":"kyc","node":"tiers","title":"KYC straight-through processing","body":"KYC failures are classified across five layers and 24 modes, then routed: auto-resolve what the system can fix, guide the borrower through what they can fix, and send only the rest to a human.","detects":"Borrowers dropped for failures that never needed a human.","callout":{"t":"KYC STP","h":"L1–L5 → T1 / T2 / T3","d":"Deterministic routing from failure mode to resolution tier."}}],"stack":[["Data",["PostgreSQL","Append-only events","Metric contracts","Identity resolution"]],["Statistics",["Beta-binomial posteriors","Rolling windows","Anomaly detection"]],["LLM layer",["Insight Object schema","Hypothesis library","Numeric validator"]],["KYC",["V-CIP","eKYC","CKYC","Account Aggregator","Failure taxonomy"]],["Platform",["Azure","FastAPI","CRM write-back"]]],"decisions":[{"h":"Bayesian over z-scores","c":"Beta-binomial posteriors on small samples","p":"Per-project weekly volumes are too small for normal approximations; posteriors express uncertainty honestly.","t":"Harder to explain than a percentage; mitigated by plain-language alerts."},{"h":"LLM as renderer only","c":"Numbers come from the object, never the model","p":"A narrated insight with a wrong number destroys trust in the whole system.","t":"Less flexible prose; far more reliable."},{"h":"Non-surveillance by schema","c":"Rep identifiers physically excluded from insight tables","p":"A policy promise can be broken by one query; a schema can't. Reporting stays at project and team level.","t":"Some coaching use cases need a separate, consented path."},{"h":"Taxonomy before automation","c":"Map all 24 failure modes first","p":"You can't auto-resolve what you haven't classified. The taxonomy makes routing deterministic and auditable.","t":"Upfront analysis time before any automation ships."}],"showInGrid":false},{"slug":"production-rag","tag":"Open source · Technical series","title":"Production RAG Architecture","lede":"A reference implementation and 20–25 part series that takes RAG from a notebook demo to a production system, one stage at a time. Each stage is specified with an explicit contract, the ways it fails, and the evaluation gate that catches the failure.","meta":["Personal project","In progress","Towards AI · Medium"],"metrics":[["20–25","planned posts"],["8","pipeline stages"],["1","contract per stage"]],"status":"In progress: stage breakdown reflects the planned series structure.","problem":"Most RAG tutorials stop at 'embed, retrieve, generate'. Production systems fail in the seams between stages: tables split by chunkers, stale embeddings, retrieval that looks fine until a user asks about a number. The series treats each seam as a contract.","role":["Series design and writing","Reference implementation","Evaluation gates per stage"],"links":[["View repo ↗","https://github.com/Alwyn25/Production-RAG-Architecture--Stage-by-Stage-Contracts-Failures-Fixes"]],"arch":{"cols":["INGEST","INDEX","RETRIEVE","GENERATE","EVALUATE"],"nodes":[{"id":"ingest","label":"Ingestion","sub":"parse · normalize","col":0,"row":0,"desc":"Parse documents into a canonical record with source, version, and checksum.","tech":["Python","FastAPI"],"contract":"doc_id · source · version · checksum · blocks[]"},{"id":"chunk","label":"Chunking","sub":"structure-aware","col":0,"row":1,"desc":"Split on document structure, keeping tables and headings intact and carrying parent context.","tech":["Semantic chunking"]},{"id":"embed","label":"Embedding","sub":"versioned model","col":1,"row":0,"desc":"Every vector records the embedding model version, so re-indexing is a controlled migration.","tech":["Embedding models"]},{"id":"index","label":"Hybrid index","sub":"pgvector + FTS","col":1,"row":1,"desc":"Dense and lexical indexes in PostgreSQL, one system of record.","tech":["pgvector","tsvector"]},{"id":"retrieve","label":"Retrieve + RRF","sub":"dense ∪ lexical","col":2,"row":0,"desc":"Parallel dense and lexical retrieval merged with Reciprocal Rank Fusion.","tech":["RRF"]},{"id":"rerank","label":"Rerank","sub":"precision@k","col":2,"row":1,"desc":"A second-stage reranker trades a little latency for much better precision at the top.","tech":["Cross-encoder"]},{"id":"gen","label":"Generate","sub":"cited answers","col":3,"row":0,"desc":"Answers must cite chunk IDs; uncited claims are treated as failures.","tech":["LLM","Citations"]},{"id":"guard","label":"Guardrails","sub":"refuse · ground","col":3,"row":1,"decide":true,"desc":"Refuse when retrieval confidence is low instead of guessing.","tech":["Guardrails"]},{"id":"eval","label":"Evaluation gates","sub":"Ragas · DeepEval","col":4,"row":0,"decide":true,"desc":"Faithfulness, answer relevance, and context precision gate every change.","tech":["Ragas","DeepEval"]},{"id":"obs","label":"Observability","sub":"traces · drift","col":4,"row":1,"desc":"Per-stage traces and retrieval drift monitoring in production.","tech":["Tracing"]}],"edges":[["ingest","chunk"],["chunk","embed"],["embed","index"],["index","retrieve"],["retrieve","rerank"],["rerank","gen"],["gen","guard"],["guard","eval"],["eval","obs"]]},"walkTitle":"Each stage: contract, failure, fix","walkSub":"Scroll through the pipeline. Each stage shows the data contract passed to the next stage and the failure it guards against.","scene":"arch","steps":[{"k":"ingest","node":"ingest","title":"Ingestion contract","body":"Every document becomes a canonical record with a checksum and version before anything else touches it.","fail":"Silent re-ingestion of changed files leaves stale answers. Fix: checksum-based change detection.","payload":"{ \"doc_id\": \"policy-042\", \"version\": 3,\n  \"checksum\": \"sha256:…\", \"blocks\": [ … ] }"},{"k":"chunk","node":"chunk","title":"Structure-aware chunking","body":"Chunks follow headings and keep tables whole, each carrying its parent section title.","fail":"Fixed-size splitting cuts tables in half, so numeric answers come back wrong. Fix: structural boundaries."},{"k":"embed","node":"embed","title":"Versioned embeddings","body":"Each vector stores the model that produced it. Upgrading models becomes a planned re-index, not a mixed index.","fail":"Mixing embedding versions silently degrades similarity. Fix: version column + migration."},{"k":"retrieve","node":"retrieve","title":"Hybrid retrieval with RRF","body":"Dense search finds meaning; lexical search finds exact terms like policy IDs. RRF merges the rankings without tuning score scales.","fail":"Dense-only retrieval misses exact identifiers. Fix: hybrid + RRF."},{"k":"rerank","node":"rerank","title":"Reranking","body":"A reranker reorders the top candidates so the few chunks the LLM sees are the right ones.","fail":"Relevant chunk at rank 9 never reaches the prompt. Fix: rerank before truncation."},{"k":"gen","node":"guard","title":"Grounded, cited generation","body":"The model must cite chunk IDs, and low retrieval confidence triggers a refusal instead of a guess.","fail":"Fluent answers with no support. Fix: citation requirement + confidence threshold."},{"k":"eval","node":"eval","title":"Evaluation gates","body":"Faithfulness, relevance, and context precision run on a fixed question set for every change, like unit tests for retrieval.","fail":"Regressions ship unnoticed. Fix: Ragas/DeepEval gates in CI."}],"stack":[["Core",["Python","FastAPI"]],["Retrieval",["PostgreSQL","pgvector","tsvector","RRF","Reranking"]],["Quality",["Ragas","DeepEval","Citations","Guardrails"]],["Platform",["Azure","Docker"]]],"decisions":[{"h":"Postgres as the retrieval store","c":"pgvector + tsvector in one database","p":"One system for metadata, vectors, and full-text keeps joins, transactions, and backups simple.","t":"Very large corpora may eventually need a dedicated vector engine."},{"h":"Contracts between stages","c":"Typed payloads at every seam","p":"Most RAG bugs are seam bugs. Explicit contracts make them testable.","t":"More upfront schema work."}],"showInGrid":true,"card":{"k1":"open source · series","k2":"in progress","text":"A reference implementation and 20–25 part technical series taking RAG from baseline to production. Every stage ships with explicit contracts, documented failure modes, and evaluation gates.","chips":["Python","FastAPI","Azure","pgvector"],"cta":"stage-by-stage breakdown","wide":true}},{"slug":"ai-skill-suite","tag":"Tooling · AI workflows","title":"AI Engineering Skill Suite","lede":"Engineering standards turned into reusable Claude skills, so architecture reviews and technical writing follow the same playbook every time instead of depending on how a prompt was phrased that day.","meta":["Personal project","2026"],"metrics":[["3","production skills"],["2","reference packs"],["1","research → publish pipeline"]],"problem":"Ad hoc prompting gives inconsistent output: one session remembers audit logging, the next forgets it. Standards that live only in someone's head don't scale.","role":["Designed and wrote all three skills","Built the research-to-publication handoff"],"arch":{"cols":["INPUT","RESEARCH","HANDOFF","PRODUCE"],"nodes":[{"id":"topic","label":"Topic / system","sub":"request","col":0,"row":0,"desc":"A topic to write about, or a system to architect.","tech":[]},{"id":"radar","label":"tech-advancement-radar","sub":"skill","col":1,"row":0,"desc":"Researches the latest advancements in a topic: the bottleneck each one solves and where it fits in production systems.","tech":["Research skill"]},{"id":"brief","label":"Handoff brief","sub":"structured","col":2,"row":0,"desc":"A structured brief passed from research to writing, so the writer never starts from a blank page.","tech":["Contract"]},{"id":"blog","label":"medium-technical-blog","sub":"skill","col":3,"row":0,"desc":"Plans, drafts, and edits Medium articles against a writing blueprint and a curated knowledge base.","tech":["Writing skill"]},{"id":"arch","label":"enterprise-ai-platform-architect","sub":"skill","col":1,"row":1,"desc":"Architecture skill for regulated enterprise AI: deterministic ML, forensic-grade auditability, and governance as infrastructure.","tech":["SKILL.md"]},{"id":"refs","label":"Reference packs","sub":"Azure · MLOps","col":2,"row":1,"desc":"azure-ai-stack.md (compute, orchestration, storage, security, reference architectures) and mlops-patterns.md.","tech":["azure-ai-stack.md","mlops-patterns.md"]},{"id":"design","label":"Architecture doc","sub":"audit-ready","col":3,"row":1,"decide":true,"desc":"Implementation-oriented architecture with explicit layer responsibilities, contracts, and compliance (GDPR, SOC2, financial regulation).","tech":[]}],"edges":[["topic","radar"],["radar","brief"],["brief","blog"],["topic","arch"],["arch","refs"],["refs","design"]]},"walkTitle":"How the skills compose","walkSub":"Scroll to follow both pipelines.","scene":"arch","steps":[{"k":"radar","node":"radar","title":"Research with a point of view","body":"The radar skill doesn't just list new techniques; for each it names the bottleneck it solves and whether it helps a production system."},{"k":"brief","node":"brief","title":"A contract between skills","body":"Research hands off a structured brief, the same idea as a pipeline contract, so the writing skill starts grounded.","payload":"{ \"topic\": \"hybrid retrieval\",\n  \"advancements\": [ { \"name\": …, \"bottleneck\": …, \"production_fit\": … } ],\n  \"angle\": \"…\" }"},{"k":"blog","node":"blog","title":"Writing to a blueprint","body":"The blog skill applies a written blueprint of engineering and editorial standards, so every article meets the same bar."},{"k":"arch","node":"design","title":"Architecture with governance built in","body":"The enterprise architect skill carries reference packs for Azure and MLOps, and treats compliance and auditability as first-class requirements, not appendices."}],"stack":[["Skills",["Claude skills","SKILL.md","Reference packs"]],["Domains",["Azure AI stack","MLOps patterns","GDPR","SOC2"]]],"decisions":[{"h":"Skills over prompts","c":"Versioned instructions, not chat history","p":"A skill is reviewable and improvable like code; a prompt is gone when the chat ends.","t":"Skills need maintenance as tools evolve."},{"h":"Separate research from writing","c":"Two skills joined by a brief","p":"Each does one job well, and the brief is inspectable.","t":"One extra step per article."}],"showInGrid":true,"card":{"k1":"tooling","k2":"AI workflows","text":"Reusable Claude skills that encode engineering standards: an enterprise AI platform architect and a research-to-publication pipeline.","chips":["MLOps patterns","Governance"],"cta":"how it works"}},{"slug":"pdf-intelligence","tag":"LLM · RAG","title":"Conversational PDF Intelligence","lede":"Ask questions of long, complex PDFs in plain language. LangChain RAG with semantic chunking and conversation memory, so follow-up questions keep their context.","meta":["Personal project","Open source"],"metrics":[["RAG","retrieval-grounded answers"],["Memory","context across turns"]],"problem":"Long reports bury the answer on page 47. Keyword search needs the exact phrase; reading takes an hour.","role":["Built end to end"],"links":[["View repo ↗","https://github.com/Alwyn25/Chat-with-PDFs"]],"arch":{"cols":["LOAD","INDEX","CONVERSE"],"nodes":[{"id":"upload","label":"PDF upload","sub":"parse text","col":0,"row":0,"desc":"PDFs are loaded and their text extracted page by page.","tech":["LangChain loaders"]},{"id":"chunk","label":"Semantic chunking","sub":"meaning-based","col":0,"row":1,"desc":"Text is split on meaning rather than fixed length, so chunks hold complete ideas.","tech":["Semantic chunking"]},{"id":"embed","label":"Embeddings","sub":"vector store","col":1,"row":0,"desc":"Chunks are embedded and stored for similarity search.","tech":["Embeddings","Vector store"]},{"id":"retr","label":"Retriever","sub":"top-k","col":1,"row":1,"desc":"The question retrieves the most relevant chunks.","tech":["LangChain retriever"]},{"id":"mem","label":"Chat memory","sub":"history-aware","col":2,"row":0,"desc":"Follow-ups are rewritten with conversation context before retrieval.","tech":["Conversation memory"]},{"id":"llm","label":"LLM answer","sub":"grounded","col":2,"row":1,"decide":true,"desc":"The LLM answers from the retrieved chunks only.","tech":["LLM"]}],"edges":[["upload","chunk"],["chunk","embed"],["embed","retr"],["mem","retr"],["retr","llm"],["llm","mem"]]},"walkTitle":"From PDF to answer","walkSub":"Scroll through a question and a follow-up.","scene":"arch","steps":[{"k":"u","node":"upload","title":"Load the document","body":"Text is extracted from each page of the PDF."},{"k":"c","node":"chunk","title":"Chunk by meaning","body":"Semantic chunking keeps whole ideas together, which directly improves what retrieval finds."},{"k":"r","node":"retr","title":"Retrieve","body":"The question is embedded and matched against the chunks.","payload":"Q: \"What was the Q3 revenue growth?\"\n→ top-k chunks: p.12 §3.1, p.13 table 2"},{"k":"m","node":"mem","title":"Remember the conversation","body":"'And for Q4?' only makes sense with history. Memory rewrites the follow-up into a standalone question before retrieval.","payload":"\"And for Q4?\"  →  \"What was the Q4 revenue growth?\""},{"k":"l","node":"llm","title":"Answer from the source","body":"The LLM answers using only the retrieved chunks."}],"stack":[["Core",["Python","LangChain","RAG"]],["Retrieval",["Semantic chunking","Embeddings","Vector store","Chat memory"]]],"decisions":[{"h":"Semantic over fixed-size chunks","c":"Split on meaning","p":"Chunks that hold complete ideas retrieve better and answer better.","t":"Chunking is slower than fixed windows."}],"showInGrid":true,"card":{"k1":"LLM · RAG","k2":"github","text":"LangChain RAG with semantic chunking and context-preserving memory for natural-language querying over complex documents.","chips":["LangChain","RAG"],"cta":"architecture"}},{"slug":"number-plate-detection","tag":"Computer vision","title":"Real-Time Number Plate Detection","lede":"A real-time pipeline that spots vehicles' number plates in video, reads them with OCR, and logs every read to a database for downstream analytics.","meta":["Personal project","Open source"],"metrics":[["YOLOv9","detector"],["Real-time","video frames"],["SQLite","vehicle log"]],"problem":"Manual gate and parking logs are slow and error-prone. Reading plates from video automatically needs detection, cropping, and OCR working together in real time.","role":["Built end to end"],"links":[["View repo ↗","https://github.com/Alwyn25/number-plate-detection-real-time"]],"arch":{"cols":["CAPTURE","DETECT","READ","STORE"],"nodes":[{"id":"cam","label":"Video frames","sub":"OpenCV","col":0,"row":0,"desc":"Frames are captured from a camera or video stream.","tech":["OpenCV"]},{"id":"yolo","label":"YOLOv9 detector","sub":"plate boxes","col":1,"row":0,"desc":"Detects number plates and returns bounding boxes with confidence scores.","tech":["YOLOv9"]},{"id":"crop","label":"Crop & preprocess","sub":"OpenCV","col":1,"row":1,"desc":"Plate regions are cropped and cleaned up to improve OCR.","tech":["OpenCV"]},{"id":"ocr","label":"OCR","sub":"plate text","col":2,"row":0,"desc":"Reads the characters on each plate crop.","tech":["OCR"]},{"id":"db","label":"SQLite log","sub":"timestamped reads","col":3,"row":0,"decide":true,"desc":"Each read is stored with a timestamp for vehicle logging.","tech":["SQLite"]},{"id":"an","label":"Analytics","sub":"downstream","col":3,"row":1,"desc":"Logged reads feed counts, dwell times, and other analytics.","tech":[]}],"edges":[["cam","yolo"],["yolo","crop"],["crop","ocr"],["ocr","db"],["db","an"]]},"walkTitle":"One frame through the pipeline","walkSub":"Scroll to follow a single frame. Visuals are illustrative.","scene":"plate","steps":[{"k":"frame","node":"cam","title":"Capture the frame","body":"OpenCV reads frames from the stream."},{"k":"detect","node":"yolo","title":"Detect the plate","body":"YOLOv9 finds the plate and returns a bounding box with a confidence score.","callout":{"t":"YOLOv9","h":"Plate detected","d":"Bounding box + confidence."}},{"k":"crop","node":"crop","title":"Crop and clean","body":"The plate region is cropped and preprocessed so OCR sees clean characters."},{"k":"ocr","node":"ocr","title":"Read the characters","body":"OCR converts the crop into text.","callout":{"t":"OCR","h":"KL 07 AB 1234","d":"Illustrative plate."}},{"k":"log","node":"db","title":"Log it","body":"The read is written to SQLite with a timestamp, ready for analytics.","payload":"INSERT INTO vehicle_log (plate, seen_at)\nVALUES (\"KL07AB1234\", \"2026-09-30 10:42:07\");"}],"stack":[["Vision",["YOLOv9","OpenCV","OCR"]],["Storage",["SQLite"]],["Language",["Python"]]],"decisions":[{"h":"Detect, then read","c":"Two-stage pipeline","p":"OCR on a tight plate crop is far more accurate than OCR on a full frame.","t":"Two models' latency per frame."}],"showInGrid":true,"card":{"k1":"computer vision","k2":"github","text":"YOLOv9 + OpenCV + OCR pipeline with SQLite logging for automated vehicle tracking and analytics.","chips":["YOLOv9","OpenCV","OCR"],"cta":"frame-by-frame pipeline"}},{"slug":"demand-forecasting","tag":"Forecasting · Operations","title":"Demand Forecasting & Replenishment","lede":"Product-level daily demand forecasts across a vending machine network, turned into restock decisions with dynamic safety stock.","meta":["Lanware Solutions","Associate Engineer","2023"],"metrics":[["92%","daily forecast accuracy"],["−20%","stockout incidents"],["−12%","spoilage"],["25%","faster data retrieval"]],"problem":"Restocking on a fixed schedule meant popular items ran out while perishables expired in other machines.","role":["Built forecasting models","Built the replenishment engine","Built the REST ingestion pipeline"],"arch":{"cols":["DATA","FEATURES","MODELS","DECIDE"],"nodes":[{"id":"api","label":"REST ingestion","sub":"sales · stock","col":0,"row":0,"desc":"Automated pulls of sales and stock data from field systems.","tech":["REST APIs"]},{"id":"fe","label":"Feature engineering","sub":"calendar · lags","col":1,"row":0,"desc":"Seasonality, day-of-week, location, and lag features per product and machine.","tech":["Pandas"]},{"id":"xgb","label":"XGBoost","sub":"feature-rich","col":2,"row":0,"desc":"Gradient-boosted model capturing feature interactions.","tech":["XGBoost"]},{"id":"prophet","label":"Prophet","sub":"seasonality","col":2,"row":1,"desc":"Time-series model for trend and seasonal patterns.","tech":["Prophet"]},{"id":"ss","label":"Safety stock","sub":"dynamic","col":3,"row":0,"decide":true,"desc":"Safety stock recalculated from forecast uncertainty, not a fixed buffer.","tech":["Inventory rules"]},{"id":"plan","label":"Restock plan","sub":"per machine","col":3,"row":1,"desc":"Replenishment quantities per product per machine.","tech":["Power BI"]}],"edges":[["api","fe"],["fe","xgb"],["fe","prophet"],["xgb","ss"],["prophet","ss"],["ss","plan"]]},"walkTitle":"From sales history to a restock decision","walkSub":"Scroll through the pipeline. The chart uses illustrative data.","scene":"forecast","steps":[{"k":"hist","node":"api","title":"Sales history","body":"Daily product-level sales arrive through an automated REST pipeline."},{"k":"fc","node":"xgb","title":"Forecast demand","body":"XGBoost and Prophet forecast next-week daily demand per product and machine.","callout":{"t":"Forecast","h":"92% daily accuracy","d":"Product-level, per machine."}},{"k":"band","node":"ss","title":"Size the buffer from uncertainty","body":"Safety stock follows the forecast's uncertainty band: wide band, bigger buffer.","detects":"Stockouts on volatile items, over-stocking on stable ones."},{"k":"restock","node":"plan","title":"Restock the right amount","body":"The plan restocks to forecast plus safety stock, cutting stockouts by 20% and spoilage by 12%.","callout":{"t":"Outcome","h":"−20% stockouts · −12% spoilage","d":"Measured against the fixed-schedule baseline."}}],"stack":[["Models",["XGBoost","Prophet","Feature engineering"]],["Data",["REST APIs","Pandas","NumPy"]],["Reporting",["Power BI"]]],"decisions":[{"h":"Two model families","c":"XGBoost + Prophet","p":"Boosting captures feature interactions; Prophet captures seasonality. Together they cover both demand patterns.","t":"Two models to monitor."},{"h":"Uncertainty-driven safety stock","c":"Buffer tracks forecast band","p":"A fixed buffer over-stocks stable items and under-stocks volatile ones.","t":"Requires calibrated uncertainty estimates."}],"showInGrid":true,"card":{"k1":"forecasting","k2":"ml","text":"Product-level vending demand forecasts at 92% accuracy, with dynamic safety stock cutting stockouts by 20%.","chips":["XGBoost","Prophet"],"cta":"forecast to restock"}}]$pf_seed$::jsonb) on conflict (key) do nothing;
